begin;
do $$declare u uuid;u2 uuid;me uuid;reviewer uuid;w uuid;patient uuid;provider uuid;service uuid;tpl uuid;pkg uuid;ag uuid;appt uuid;visit uuid;ord uuid;s jsonb;r jsonb;d date:=(now() at time zone 'Africa/Cairo')::date;t timestamptz;key uuid:=gen_random_uuid();prefix text:='ROLLBACK-'||gen_random_uuid()::text;
begin
 select user_id,id into u,me from public.admins where active and user_id is not null and role='super_admin' order by id limit 1;
 select user_id,id into u2,reviewer from public.admins where active and user_id is not null and id<>me order by id limit 1;
 if u is null or u2 is null then raise exception 'Two existing active users required';end if;
 perform set_config('request.jwt.claim.sub',u::text,true);execute 'set local role authenticated';
 w:=public.clinic_reception_bootstrap();s:=public.clinic_reception_snapshot(w,d,d);if s->'workspace'->>'mode'<>'trial' then raise exception 'Trial only';end if;
 patient:=(s->'patients'->0->>'id')::uuid;provider:=(s->'providers'->0->>'id')::uuid;
 perform public.clinic_reception_command(w,'member',jsonb_build_object('admin_id',reviewer,'capabilities',jsonb_build_array('view','review')),gen_random_uuid());
 service:=(public.clinic_reception_command(w,'service',jsonb_build_object('code',prefix,'name','خدمة فحص تتراجع بالكامل','department','عيادة تجربة','price',300,'minutes',20),gen_random_uuid())->>'id')::uuid;
 ag:=(public.clinic_reception_command(w,'agreement',jsonb_build_object('provider_id',provider,'service_code',prefix,'rate',20,'from',d,'to',d+1,'reference',prefix),gen_random_uuid())->>'id')::uuid;
 perform set_config('request.jwt.claim.sub',u2::text,true);perform public.clinic_reception_command(w,'agreement_review',jsonb_build_object('id',ag,'approve',true),gen_random_uuid());
 perform set_config('request.jwt.claim.sub',u::text,true);
 tpl:=(public.clinic_reception_command(w,'template',jsonb_build_object('code',prefix,'name','باكج فحص متراجع','price',500,'visits',2,'validity_days',30,'terms','فحص تجريبي لا يحفظ','lines',jsonb_build_array(jsonb_build_object('visit_no',1,'service_id',service,'quantity',1),jsonb_build_object('visit_no',2,'service_id',service,'quantity',1))),gen_random_uuid())->>'id')::uuid;
 pkg:=(public.clinic_reception_command(w,'package_sell',jsonb_build_object('template_id',tpl,'patient_id',patient),gen_random_uuid())->>'id')::uuid;
 r:=public.clinic_reception_command(w,'collect',jsonb_build_object('patient_id',patient,'package_id',pkg,'amount',600,'method','instapay','reference',prefix),key);
 if public.clinic_reception_command(w,'collect',jsonb_build_object('patient_id',patient,'package_id',pkg,'amount',600,'method','instapay','reference',prefix),key)<>r then raise exception 'Duplicate receipt';end if;
 t:=(d::text||' 23:00:00')::timestamp at time zone 'Africa/Cairo';
 perform public.clinic_reception_command(w,'availability',jsonb_build_object('provider_id',provider,'starts_at',t,'ends_at',t+interval '1 hour'),gen_random_uuid());
 appt:=(public.clinic_reception_command(w,'book',jsonb_build_object('patient_id',patient,'provider_id',provider,'service_id',service,'starts_at',t,'package_id',pkg,'package_visit_no',1),gen_random_uuid())->>'id')::uuid;
 visit:=(public.clinic_reception_command(w,'arrive',jsonb_build_object('id',appt),gen_random_uuid())->>'id')::uuid;
 s:=public.clinic_reception_snapshot(w,d,d);select (x->>'id')::uuid into ord from jsonb_array_elements(s->'orders') x where x->>'visit_id'=visit::text;
 perform public.clinic_reception_command(w,'execute',jsonb_build_object('id',ord,'materials','[]'::jsonb),gen_random_uuid());
 execute 'reset role';
 if (select recognized from clinic_reception.packages where id=pkg)<>250 then raise exception 'Wrong recognized revenue';end if;
 if (select doctor_fee from clinic_reception.orders where id=ord)<>50 then raise exception 'Wrong doctor fee';end if;
 if exists(select 1 from clinic_reception.journal j join clinic_reception.journal_lines l on l.entry_id=j.id where j.workspace_id=w group by j.id having sum(debit)<>sum(credit)) then raise exception 'Unbalanced journal';end if;
 if exists(select 1 from clinic_reception.journal where workspace_id=w and finance_entry_id is not null) then raise exception 'Trial touched live ledger';end if;
end $$;
rollback;
select jsonb_build_object('test','packages authenticated production rollback passed','anonymous_blocked',not has_function_privilege('anon','public.clinic_reception_command(uuid,text,jsonb,uuid)','execute'));
